export const SKETCH_NAMES = Object.keys(S);

// <Sketch name="car" /> : hauteur fixe (size), largeur selon le viewBox ; aria-hidden (le sens est porté par le texte à côté).
export default function Sketch({ name, size = 40, className }: { name: string; size?: number; className?: string }) {
  const d = S[name];
  if (!d) return null;
  const [, , w, h] = d.vb.split(" ").map(Number);
  return (
    <svg className={"sketch" + (className ? " " + className : "")} viewBox={d.vb} height={size} width={Math.round((size * w) / h)}
         fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"
         dangerouslySetInnerHTML={{ __html: d.svg }} />
  );
}
